entries[196435] = { ["name"] = "Scytherins Stacheldrahtkette", ["text"] = "Wird beim Aufheben gebunden\nHals\n+32 Ausdauer\nErhöht Eure kritische Trefferwertung um + 41.\nErhöht Eure Tempowertung um + 65.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, das Ziel mit einem Dorn zu durchbohren und ihm 138 körperlichen Schaden zuzufügen.\nVerkaufspreis:" }
