entries[197793] = { ["name"] = "Yusas herzhafter Eintopf", ["text"] = "Benutzen: Stellt einen frischen Topf mit Yusas herzhaftem Eintopf auf, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer niedrigster Sekundärwert wird 1 Stunde lang um 70 erhöht.\nVerkaufspreis:" }
entries[197794] = { ["name"] = "Großbankett der Kalu'ak", ["text"] = "Benutzen: Richtet für 3 Min. ein traditionelles Festmahl der Tuskarr aus, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer Primärwert wird 1 Stunde lang um 76 erhöht.\nVerkaufspreis:" }
entries[197795] = { ["name"] = "Vorrat an drakonischen Delikatessen", ["text"] = "Unbekannte Bindungsart\nBenutzen: Richtet einen wachsenden Vorrat an drakonischen Delikatessen her, der mit köstlichen zubereiteten Mahlzeiten sowie überschüssigen Zutaten bestückt werden kann. Stellt das Festmahl fertig, damit alle es genießen können!\n\nDas fertige Festmahl stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer Primärwert wird 1 Stunde lang um 76 erhöht.\nVerkaufspreis:" }
