entries[198036] = { ["name"] = "Wirbelreißers Reißzahn", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+28 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe haben eine Chance, das Ziel auszuweiden und ihm so 480 körperlichen Schaden zuzufügen. Verursacht den doppelten Schaden, wenn Ihr Euch hinter Eurem Ziel befindet.\nVerkaufspreis:" }
entries[198037] = { ["name"] = "Überladener Arkanokristall", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, die Energien um Euch zu arkanokristallisieren, was 16 Sek. lang einen fluktuierenden Sekundärwert erhöht.\nVerkaufspreis:" }
entries[198038] = { ["name"] = "Uralter Titanenstahlbarren", ["text"] = "Questgegenstand\n\"Diese Barren wurden von Aggramar persönlich geschmiedet und dienten dazu, Azeroths ursprüngliche Hüter zu schaffen.\"" }
entries[198039] = { ["name"] = "Stein der Anerkennung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ruft ein dankbares Kleintier herbei, um ein Festmahl als Zeichen der Dankbarkeit herzurichten. (1 Stunde Abklingzeit)" }
entries[198040] = { ["name"] = "Sonnengegerbtes Leinen", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Gemütlich und warm.\"" }
entries[198041] = { ["name"] = "Linke Klinge der Khaz'goritstoffschere", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+428 Intelligenz\n+261 Ausdauer\nErhöht Eure kritische Trefferwertung um + 168.\n+ 90 Vielseitigkeit\nVerkaufspreis:" }
entries[198042] = { ["name"] = "Betäubende Pollen", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Ein aromatisches, pappiges Pulver, von dem Euch die Finger taub werden!\"" }
entries[198043] = { ["name"] = "Verstohlener Elfenwein", ["text"] = "Einzigartig (100)\nBenutzen: Ein starkes alkoholisches Getränk.\n\"Ein durchdringender Geschmack, der sich schleichend einstellt.\"" }
entries[198044] = { ["name"] = "Wirbelwindwein", ["text"] = "Einzigartig (100)\nBenutzen: Ein starkes alkoholisches Getränk.\n\"Durch das wilde Schütteln ist der Inhalt ziemlich schaumig geworden.\"" }
entries[198045] = { ["name"] = "Krach-Bumm-Gesöff", ["text"] = "Einzigartig (100)\nBenutzen: Ein starkes alkoholisches Getränk.\n\"Ein seltenes Gebräu, das man kaum außerhalb von Pandaria findet.\"" }
entries[198046] = { ["name"] = "Konzentrierte urzeitliche Infusion", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+50 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Genialität hergestellt werden.\n\"Von ihr geht kaum eingedämmte Elementarenergie aus.\"\nVerkaufspreis:" }
entries[198047] = { ["name"] = "Kul Tiraner Rot", ["text"] = "Einzigartig (20)\nBenutzen: Wirft eine Flasche nach dem aktuellen Ziel.\n\"Eine billiger Verschnitt, der häufiger geschmissen als getrunken wird.\"\nVerkaufspreis:" }
entries[198048] = { ["name"] = "Trainingsmatrix der Titanen I", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+20 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Rüstungsteile und Zubehör.\n\"Leider kann man kaum in Worte fassen, was die Titanenmatrix ist. Man muss sie einfach selbst gesehen haben.\"\nVerkaufspreis:" }
entries[198056] = { ["name"] = "Trainingsmatrix der Titanen II", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+40 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Leider kann man kaum in Worte fassen, was die Titanenmatrix ist. Man muss sie einfach selbst gesehen haben.\"\nVerkaufspreis:" }
entries[198058] = { ["name"] = "Trainingsmatrix der Titanen III", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+60 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Leider kann man kaum in Worte fassen, was die Titanenmatrix ist. Man muss sie einfach selbst gesehen haben.\"\nVerkaufspreis:" }
entries[198059] = { ["name"] = "Trainingsmatrix der Titanen IV", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+140 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Leider kann man kaum in Worte fassen, was die Titanenmatrix ist. Man muss sie einfach selbst gesehen haben.\"\nVerkaufspreis:" }
entries[198070] = { ["name"] = "Zerrissene Seeranke", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig\n\"Angler Tinnak war außergewöhnlich gut im Flechten von Harpunenseilen. Aber er ist seit einiger Zeit verschwunden und wurde zuletzt in den Oberen Frostlanden in der Nähe des Lagers Antonidas gesehen. Bringt sie zu Tavio in Iskaara.\"" }
entries[198071] = { ["name"] = "Flammengeschnitzter Knochen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dieser Knochen ist von Djaradinrunen bedeckt.\"" }
entries[198072] = { ["name"] = "Goldgefasster Drachenzahn", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Der Überrest eines gefallenen Drachen.\"" }
entries[198073] = { ["name"] = "Karha, der stille Wind", ["text"] = "Questgegenstand\nEinzigartig\n\"Karha war der Stab von Ganmat dem Weisen, einem alten Windweisen von Ohn'ahra, der vor Jahrhunderten unzählige Verbündete heilte und noch mehr Gegner besiegte.\"" }
entries[198074] = { ["name"] = "Josanak der sichere Sieg", ["text"] = "Questgegenstand\nEinzigartig\n\"Josanak gehörte dem unbezwungenen Krieger Zaphil. Zaphil konnte sich stets auf seine Hellebarde verlassen, so wie auch sein Klan sich stets auf ihn verlassen konnte.\"" }
entries[198075] = { ["name"] = "Tsegzaya der Dornenbogen", ["text"] = "Questgegenstand\nEinzigartig\n\"Als Dihar noch den Bogen gespannt hat, haben unzählige Pfeile von Tsegzaya ihr Ziel gefunden, egal, ob es sich dabei um Wildtiere oder die Feinde des Klans Teerai gehandelt hat.\"" }
entries[198076] = { ["name"] = "Ungeziefervernebler", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft einen Ungeziefervernebler, der eine giftige Explosion auslöst, die allen Gegnern innerhalb von 6 Metern 15 Naturschaden zufügt, sie zurückstößt und ihre Bewegungsgeschwindigkeit für 8 Sek. um 30% verringert.\n\nDer Rückstoßeffekt ist bei gegnerischen Spielercharakteren wirksamer." }
entries[198078] = { ["name"] = "Rekrutierungsliste", ["text"] = "Questgegenstand\n70 ( 70)\n\"Seiten voller Rekrutierungsstrategien und Anweisungen, um ein Artefakt in den Ruinen von Nelthazan zu finden.\"" }
entries[198079] = { ["name"] = "Befehle von Sarkareth", ["text"] = "Questgegenstand\n70 ( 70)\n\"Die Aspekte tragen ihre Schuld als Komplizen bei den Verbrechen des Zerstörers. Findet Beweise für ihr Vorhaben, uns zu kontrollieren. Erhebt Eure Stimme! Widersteht! - Schuppenkommandant Sarkareth\"" }
entries[198080] = { ["name"] = "Siegel der Stürme", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Mit den nicht entzifferbaren Inschriften und seiner schwankenden Temperatur ist dieses Siegel ein höchst interessanter Fund.\"" }
entries[198081] = { ["name"] = "Amulett des Pflegers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\nBenutzen: Wacht aufmerksam über das Ziel, was eine hohe Chance gewährt, dieses um 1847 Gesundheit zu heilen, wenn es in den nächsten 30 Sek. Heilung erhält. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[198082] = { ["name"] = "Vorbewusste Felsgruppe", ["text"] = "\"Nur ein Hauch von elementarem Bewusstsein verbleibt.\"\nVerkaufspreis:" }
entries[198083] = { ["name"] = "Expeditionsversorgungspaket", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Greift auf Euer Expeditionsversorgungspaket zu. Benutzt Vorräte der Dracheninseln, um Eure Erkundungs-, Kletter- und Katalogisierungsfähigkeiten aufzuwerten.\nBenötigt Ruhmrang 6 bei der Drachenschuppenexpedition.\n\"Ihr habt dieses Paket erhalten, weil Ihr Euch bei der Drachenschuppenexpedition Ruhm verdient habt.\"" }
entries[198085] = { ["name"] = "Schlüssel der verlorenen Obsidiantruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Der Schlüssel zur verlorenen Obsidiantruhe.\"\nVerkaufspreis:" }
entries[198086] = { ["name"] = "Dunkelmondkartenset: Inferno", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Schleudert ein schwelendes Inferno auf das Ziel, das ( 78083 * .3)- 78083 Feuerschaden verursacht. Der Schaden wird von der obenliegenden Karte des Kartensets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198087] = { ["name"] = "Dunkelmondkartenset: Raureif", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Fügt Eurem Ziel 15897 Frostschaden zu und belegt es für 4-12 Sek. mit 'Erwachender Raureif'. Stirbt das Ziel, solange 'Erwachender Raureif' aktiv ist, explodiert es und verursacht 39743 Frostschaden, der auf Gegner innerhalb eines Radius von 10 Metern aufgeteilt wird. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198088] = { ["name"] = "Dunkelmondkartenset: Tanz", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Ein 'Erfrischender Tanz' springt 6-13-mal zwischen Freunden und Gegnern innerhalb von 25 Metern hin und her und verursacht 9545 Naturschaden oder heilt um 5200 Gesundheit. Die Anzahl der Sprünge wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198089] = { ["name"] = "Dunkelmondkartenset: Behüter", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+300 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Gewährt 5-12 Sek. lang den 'Segen des Behüters' und einen Absorptionsschild in Höhe von 62801 Schaden.\nWenn der Schild verbraucht wird, während 'Segen des Behüters' aktiv ist, wird für dieselbe Dauer 1469 Vielseitigkeit gewährt. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198090] = { ["name"] = "Krug mit überschüssigem Schleim", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Schleimiges Rutschvergnügen! (15 Sek. Abklingzeit)\n\"JIPPIE!!!\"" }
