entries[198156] = { ["name"] = "Wyrmlochgenerator: Dracheninseln", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen zufälligen Ort auf den Dracheninseln zu reisen.\n\nIngenieure, die sich auf Triangulation spezialisieren, können lernen, wie man an bestimmte Orte gelangt. (30 Min Abklingzeit)\nBenötigt Ingenieurskunst der Dracheninseln (1)\nVerkaufspreis:" }
