entries[198352] = { ["name"] = "Siegel der Stürme", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Mit den nicht entzifferbaren Inschriften und seiner schwankenden Temperatur ist dieses Siegel ein höchst interessanter Fund.\"" }
entries[198353] = { ["name"] = "Schaudernetzei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[198354] = { ["name"] = "Der schwarze Locus", ["text"] = "Questgegenstand\n70 ( 70)\n\"Die Sprenkelung dieses Steins sieht aus wie Nebel am Nachthimmel und zieht Euch in seinen Bann. Ihr solltet ihn behalten.\"" }
entries[198355] = { ["name"] = "Tyrholdleitung", ["text"] = "Questgegenstand\nBenutzen: Entfesselt latente Magie auf einen Elitebewohner von Tyrhold, die Schaden verursacht und den erlittenen Schaden 20 Sek. lang erhöht. (30 Sek. Abklingzeit)\n\"In diesem Titanenrelikt pulsiert Magie.\"" }
entries[198356] = { ["name"] = "Honigimbiss", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[198357] = { ["name"] = "Aegisstein", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n13 Rüstung\nHaltbarkeit 25 / 25\n\"Es ist nicht ganz eindeutig, wofür die Djaradin diesen Stein benutzen. Er ist offensichtlich zu klein, um sie zu schützen.\"\nVerkaufspreis:" }
entries[198387] = { ["name"] = "Hammer des Ausgräbers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nBenötigt Ruhmrang 3 bei der Drachenschuppenexpedition.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[198388] = { ["name"] = "Aufgewirbeltes drakonisches Gebräu", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\nBenötigt Ruhmrang 25 beim Valdrakkenabkommen.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[198389] = { ["name"] = "Beschwerter Trankzylinder", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\nBenötigt Ruhmrang 25 beim Valdrakkenabkommen.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[198390] = { ["name"] = "Mahlen" }
entries[198395] = { ["name"] = "Glanzlose Stachelmuschel", ["text"] = "Benutzen: Öffnet die Muschel!\nVerkaufspreis:" }
entries[198397] = { ["name"] = "Regenbogenperle", ["text"] = "Handwerksmaterial\n\"Schillert in vielen verschiedenen Farben.\"\nVerkaufspreis:" }
entries[198398] = { ["name"] = "Urprotowelpenschuppe", ["text"] = "Questgegenstand\n\"Unglaublich robust und doch ziemlich flexibel.\"" }
entries[198400] = { ["name"] = "Glückshufeisen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Hufschmiedin Roscha behauptet, dass dies Euch auf Euren Jagden viel Glück bringen wird.\"\nVerkaufspreis:" }
entries[198401] = { ["name"] = "Köder für Querflossen-Flügelrossfische", ["text"] = "Benutzen: Erhöht 30 Min. lang die Chance, Querflossen-Flügelrossfische zu fangen.\nVerkaufspreis:" }
entries[198402] = { ["name"] = "Kochtopf der Maruuk", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt einen Kochtopf der Maruuk auf, der das Kochen ermöglicht. (5 Min Abklingzeit)\nBenötigt Ruhmrang 3 bei den Zentauren der Maruuk und den Abschluss der Quest \"Kultureller Austausch\".\n\"Die nomadische Lebensweise setzt tragbares Kochgeschirr voraus. Die Maruuk teilen es gern mit ihren Verbündeten.\"\nVerkaufspreis:" }
entries[198403] = { ["name"] = "Köder für Inselfinnenschwertfische", ["text"] = "Benutzen: Erhöht 30 Min. lang die Chance, Inselfinnenschwertfische zu fangen.\nVerkaufspreis:" }
entries[198404] = { ["name"] = "Abgefüllte Pheromone", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet eine Flasche voller Pheromone und lockt alle nicht anderweitig beschäftigten, häutbaren Bestien und Drachkin innerhalb von 60 Metern zu Euch.\n\nKann nur im Freien auf den Dracheninseln verwendet werden. (5 Min Abklingzeit)\nBenötigt Kürschnerei der Dracheninseln (10)\nVerkaufspreis:" }
entries[198406] = { ["name"] = "Gerissene Ranke", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Ableger vom Peitscher. Zappelt immer noch!\"" }
entries[198407] = { ["name"] = "Azurarkanverstärker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, Euren kritischen Trefferwert für 10 Sek. um 2804 zu erhöhen.\nVerkaufspreis:" }
entries[198408] = { ["name"] = "Zeitwanderernotizen", ["text"] = "Questgegenstand\n\"Eine ausführliche Anleitung zur Benutzung eines Zeitwandererstabs. Irgendjemand hat überall Notizen hingekritzelt.\"" }
entries[198409] = { ["name"] = "Persönlicher Panzer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Begebt Euch in Euren persönlichen Panzer. (1 Stunde Abklingzeit)\n\"Hier drin werdet Ihr Euch stets sicher fühlen.\"" }
entries[198410] = { ["name"] = "Zeitwandererstab", ["text"] = "Questgegenstand\n\"Ein Instrument zur Manipulation von Zeitmagie und zum Hüten der Zeitwege.\"" }
entries[198411] = { ["name"] = "Klaue der Bereitschaft", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Faustwaffe\n35 - 51 Schaden Geschwindigkeit 2.60\n(16.5 Schaden pro Sekunde)\n+15 Beweglichkeit\n+22 Ausdauer\n+ 16 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 13.\nVerkaufspreis:" }
entries[198424] = { ["name"] = "Dracheninseltierhäute verfeinern", ["text"] = "\"Verfeinert seltene Tierhäute und Schuppen von den Kreaturen der Dracheninseln zu höherer Qualität.\"" }
entries[198425] = { ["name"] = "Dracheninselleder verfeinern", ["text"] = "\"Verfeinert Leder von den Kreaturen der Dracheninseln zu höherer Qualität.\"" }
entries[198426] = { ["name"] = "Dracheninselschuppen verfeinern", ["text"] = "\"Verfeinert Schuppen von den Kreaturen der Dracheninseln zu höherer Qualität.\"" }
entries[198428] = { ["name"] = "Tuskarrdingi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ihr könnt Euch über Wasser fortbewegen." }
entries[198429] = { ["name"] = "Taifunbringer", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n33 - 46 Schaden Geschwindigkeit 3.60\n(11.0 Schaden pro Sekunde)\n+130 Intelligenz\n+44 Ausdauer\nErhöht Eure Tempowertung um + 30.\nErhöht Eure Meisterschaftswertung um + 28.\nHaltbarkeit 100 / 100\n\"Eine kleine Inschrift besagt: \"Mit besten Grüßen von Ty'foon\".\"\nVerkaufspreis:" }
entries[198430] = { ["name"] = "Zeitkapsel", ["text"] = "Questgegenstand\n\"Eine uralte Kiste. Sie wurde einst für jene kühnen Abenteurer zurückgelassen, die die Dracheninseln wiederentdecken werden.\"" }
entries[198432] = { ["name"] = "Primitives Windamulett", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+28 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, Euer Ziel in Winde zu hüllen, die einem Gegner 64 Naturschaden zufügen oder einem Verbündeten im Verlauf von 8 Sek. 112 Tempo gewähren.\nVerkaufspreis:" }
entries[198433] = { ["name"] = "zzOldDarkmoon Deckbox: Awakened Chill", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Auslöser (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198434] = { ["name"] = "zzOldDarkmoon Deckbox: Refreshing Dance", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Auslöser (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198435] = { ["name"] = "zzOldDarkmoon Deckbox: Watcher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Auslöser (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198436] = { ["name"] = "Jagdhufeisen", ["text"] = "\"Leicht. Gut, um Beute aufzuspüren.\"\nVerkaufspreis:" }
entries[198437] = { ["name"] = "Karawanenhufeisen", ["text"] = "\"Langlebig. Gut für Reisen über lange Strecken.\"\nVerkaufspreis:" }
entries[198438] = { ["name"] = "Drakonisches Rezept in der Flasche", ["text"] = "Wird beim Aufheben gebunden\n\"Eine kristallklare Flasche mit etwas darin, das wie ein Rezept aussieht. Sieht nützlich aus!\"\n<Zum Öffnen rechtsklicken>" }
entries[198439] = { ["name"] = "Altes Rezept in der Flasche", ["text"] = "Wird beim Aufheben gebunden\n\"Sie treibt wohl schon ein Weilchen durch Azeroth. Jetzt habt Ihr ein Rezept aus ferner Vergangenheit.\"\n<Zum Öffnen rechtsklicken>" }
entries[198440] = { ["name"] = "Billigfleisch", ["text"] = "\"Einfrieren oder bis gestern verzehren.\"\nVerkaufspreis:" }
entries[198441] = { ["name"] = "Donnerrückgratfilets", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Die Reste an Elektrizität prickeln beim Verzehr anregend auf der Zunge.\"\nVerkaufspreis:" }
entries[198442] = { ["name"] = "Sumpfdrossels Schrumpffusel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Lässt den Zaubernden und Gruppenmitglieder innerhalb von 40 Metern für 10 Min. schrumpfen. (3 Sek. Abklingzeit)\n\"Auf dem zerkratzten Etikett steht: \"Nur mit feinsten Zutaten aus, äh... Vertraut mir. Echt köstlich!\"\"\nVerkaufspreis:" }
entries[198443] = { ["name"] = "Relikt des Titanentempels", ["text"] = "Questgegenstand\n\"Ein sonderliches Relikt aus dem Titanentempel.\"" }
entries[198445] = { ["name"] = "Gegrillte Zandalichilis", ["text"] = "Questgegenstand\n\"Leicht süß und mit einer raffinierten Rauchnote. Aber achtet bloß auf die Samen.\"" }
entries[198446] = { ["name"] = "Edler Suramarjahrgang", ["text"] = "Questgegenstand\n\"Sorgfältig zusammengestellt, um dem geübten Dracthyrgaumen zu schmeicheln.\"" }
entries[198447] = { ["name"] = "Aus Bilgewasser importiertes Krabbenfleischimitat", ["text"] = "Questgegenstand\n\"Zu viel Salz geht gar nicht!\"" }
entries[198448] = { ["name"] = "Vorräte der Drachenschuppenexpedition", ["text"] = "Questgegenstand\n\"Verschiedene Vorräte, die der Drachenschuppenexpedition gehören.\"" }
entries[198449] = { ["name"] = "Beutel mit wundersamen Wundern", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Öffnen, um 1250 Einheiten kosmischen Flux zu erhalten.\nErfordert einen freundlichen Ruf bei den Erleuchteten.\n\"Die Erleuchteten tragen diese Beutel bei sich, während sie durch Zereth Mortis wandeln, da sie glauben, dass sie dies den Ersten näher bringen würde.\"" }
entries[198450] = { ["name"] = "Alter Krabbenpanzer", ["text"] = "Wird beim Aufheben gebunden\n\"Vor langer Zeit weggeworfen. Der Panzer ist glatt und abgerundet.\"" }
entries[198451] = { ["name"] = "Lebensflammenampulle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\nBenutzen: Öffnet die Ampulle und setzt die angestauten Lebensflammen frei. Verursacht 28339 Schaden, der auf alle Gegner innerhalb von 10 Metern aufgeteilt wird, sowie 42051 Heilung, die auf alle Verbündeten in diesem Bereich aufgeteilt wird. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[198452] = { ["name"] = "Prototyp V", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 4 std.\nBenutzen: Rüstet Prototyp V aus.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden.\n\"Eine der zahlreichen experimentellen Waffen, die nie über das Prototypstadium hinauskamen.\"\nVerkaufspreis:" }
entries[198453] = { ["name"] = "Unbeständige Azeritgranate", ["text"] = "Wird beim Aufheben gebunden\nDauer: 4 std.\nBenutzen: Fügt allen Gegnern innerhalb von 7 Metern um den Einschlagsort 29 bis 43 Arkanschaden zu.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden. (5 Sek. Abklingzeit)\n\"Auf dem Schwarzmarkt wurden ganze Kisten davon gehandelt.\"\nVerkaufspreis:" }
entries[198454] = { ["name"] = "Drakonische Schmiedekunstabhandlung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schmiedekunstwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Schmiedekunst der Dracheninseln (25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Schmieden. Kann nur einmal pro Woche gelesen werden.\"\nVerkaufspreis:" }
entries[198455] = { ["name"] = "Wirre Wurzeln", ["text"] = "Wird beim Aufheben gebunden\n\"Braun und grün, hart und weich, komplett durcheinander.\"" }
entries[198456] = { ["name"] = "Junges Olivauge", ["text"] = "Wird beim Aufheben gebunden\n\"Ein junges Olivauge, teilweise durchsichtig.\"" }
entries[198457] = { ["name"] = "Muster: Meisterkittel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen auserlesenen Kittel des stilvollen Lederverarbeiters herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Zentauren der Maruuk und Lederverarbeitung der Dracheninseln als Beruf.\nVerkaufspreis:" }
entries[198458] = { ["name"] = "Muster: Prächtige Deckung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Werkzeugtasche des Meisterjuweliers herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[198459] = { ["name"] = "Muster: Großzügige Blumentasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine üppige Botaniktasche des Kräuterkundigen herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[198460] = { ["name"] = "Flugbrutkäferstücke", ["text"] = "Questgegenstand" }
entries[198461] = { ["name"] = "Muster: Stoßfeste Handschuhe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man fabelhafte zwickfeste Handschützer des Ingenieurs herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[198462] = { ["name"] = "Muster: Feuerfeste Schürze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine feuerfeste Schürze des Schmiedekunstmeisters herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Zentauren der Maruuk und Lederverarbeitung der Dracheninseln als Beruf.\nVerkaufspreis:" }
entries[198463] = { ["name"] = "Muster: Hut des Alchemieexperten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein spektakuläres hydrophobes Kopfstück des Alchemisten herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Zentauren der Maruuk und Lederverarbeitung der Dracheninseln als Beruf.\nVerkaufspreis:" }
entries[198464] = { ["name"] = "Muster: Verstärkter Rucksack", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen herausragenden Gerbrahmen des Kürschners herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Zentauren der Maruuk und Lederverarbeitung der Dracheninseln als Beruf.\nVerkaufspreis:" }
entries[198465] = { ["name"] = "Muster: Kappe des Kürschnereiexperten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine prunkvolle Fallenstellerkappe des Kürschners herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 18 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[198474] = { ["name"] = "Staffelei des Künstlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lasst Euch inspirieren. (30 Sek. Abklingzeit)\n\"Nicht jeder hat das Zeug zum großen Künstler, aber jede Region hat das Potenzial solche hervorzubringen.\"" }
entries[198475] = { ["name"] = "Abgebrochene Leiste", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein Stück einer Goldleiste, das von einer deutlich größeren Statue abgebrochen ist.\"" }
entries[198476] = { ["name"] = "Gemälde der Vorstellung", ["text"] = "Questgegenstand\n\"Die groben Striche zeigen die Azurarchive aus der Ferne, eingehüllt in dichten Schnee. Das Werk strahlt eine gewisse Wehmut aus.\"" }
entries[198477] = { ["name"] = "Dunkelmondkartensetschachtel: Raureif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Fügt Eurem Ziel 10372 Frostschaden zu und belegt es für 4-12 Sek. mit 'Erwachender Raureif'. Stirbt das Ziel, solange 'Erwachender Raureif' aktiv ist, explodiert es und verursacht 25929 Frostschaden, der auf Gegner innerhalb eines Radius von 10 Metern aufgeteilt wird. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198478] = { ["name"] = "Dunkelmondkartensetschachtel: Tanz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Ein 'Erfrischender Tanz' springt 6-13-mal zwischen Freunden und Gegnern innerhalb von 25 Metern hin und her und verursacht 6228 Naturschaden oder heilt um 4133 Gesundheit. Die Anzahl der Sprünge wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198479] = { ["name"] = "Böenreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fliegt mit dem Gleiter und verringert 2 Min. lang Eure Fallgeschwindigkeit. Nur in Kul Tiras verwendbar. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[198480] = { ["name"] = "Die prachtvollen Becken", ["text"] = "Questgegenstand\n\"Dieses halbfertige Gemälde der Lebensbecken wird von einer fein abgestimmten Farbpalette aus Rosa, Rubinrot und sattem Grün dominiert.\"" }
entries[198481] = { ["name"] = "Dunkelmondkartensetschachtel: Behüter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Gewährt 5-12 Sek. lang den 'Segen des Behüters' und einen Absorptionsschild in Höhe von 51162 Schaden.\nWenn der Schild verbraucht wird, während 'Segen des Behüters' aktiv ist, wird für dieselbe Dauer 1230 Vielseitigkeit gewährt. Die Dauer wird durch die oberste Karte des Sets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[198482] = { ["name"] = "Die Spirale der Kurgane", ["text"] = "Questgegenstand\n\"In diesem Gemälde der Ebenen von Ohn'ahra schmiegen sich gewundene Spiralmuster um sanfte grüne Hügel. Weiße Windböen neigen derweil die Bäume zur Seite.\"" }
entries[198484] = { ["name"] = "Der Verfall von Brackenfell", ["text"] = "Questgegenstand\n\"Das Gemälde zeigt einen verrottenden Wald, bedeckt von dichtem grünen Nebel. Selbst die Leinwand riecht faulig.\"" }
entries[198485] = { ["name"] = "Zurückgelassene Schriftrolle", ["text"] = "Einzigartig\n\"Auf Drakonisch geschrieben. Das hat wohl jemand fallen lassen.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[198486] = { ["name"] = "Windschuppenreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fliegt mit dem Gleiter und verringert 2 Min. lang Eure Fallgeschwindigkeit. Nur auf den Dracheninseln verwendbar. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[198487] = { ["name"] = "Schillerndes Wasser", ["text"] = "Handwerksmaterial\n\"Eine leichte, blubbernde Flüssigkeit, die oft von Inschriftenkundigen verwendet wird. Kann von Händlern gekauft werden.\"\nVerkaufspreis:" }
entries[198488] = { ["name"] = "Stab der Entdeckung", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n33 - 46 Schaden Geschwindigkeit 3.60\n(11.0 Schaden pro Sekunde)\n+130 Intelligenz\n+44 Ausdauer\nErhöht Eure kritische Trefferwertung um + 28.\n+ 30 Vielseitigkeit\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[198489] = { ["name"] = "Traumlandschaftprisma", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Euch in einen Wachtraum zu versetzen, was Euch erhöhte Manaregeneration gewährt und Eure Meisterschaft um 1402 erhöht. Hält 20 Sek. lang an.\nVerkaufspreis:" }
entries[198490] = { ["name"] = "Kompass des Buschräubers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe haben eine Chance, den Kompass eine Richtung anzeigen zu lassen, was Euren kritischen Trefferwert, Euer Tempo, Eure Meisterschaft oder Eure Vielseitigkeit 12 Sek. lang um 2043 erhöht.\n\"Forscherveteranen wissen, dass ein Kompass der beste Weg ist, aus einer brenzligen Lage zu entkommen (oder in eine hineinzugeraten).\"\nVerkaufspreis:" }
entries[198510] = { ["name"] = "Drakonische Ingenieurskunstabhandlung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Ingenieuren. Kann nur einmal pro Woche gelesen werden.\"\nVerkaufspreis:" }
entries[198511] = { ["name"] = "Baumaterialien", ["text"] = "Questgegenstand\n\"Die zerbröckelten Überreste eines Erdelementars. Das als Baumaterialien zu bezeichnen, ist schon sehr großzügig.\"" }
entries[198512] = { ["name"] = "Die großen Hallen", ["text"] = "Questgegenstand\n\"Kaum mehr als eine Skizze. Hohe Säulen und helle Lichter schmücken dieses halbfertige Gemälde der Hallen der Infusion.\"" }
entries[198513] = { ["name"] = "Die Akademie", ["text"] = "Questgegenstand\n\"In diesem Gemälde der Akademie von Algeth'ar spielen Drakoniden unter farbenprächtigen Drachenschwarmbannern, welche an einer gewaltigen Mauer hängen.\"" }
entries[198514] = { ["name"] = "Das versiegelte Gewölbe", ["text"] = "Questgegenstand\n\"Große blaue und lila Spritzer stellen Explosionen arkaner Magie in diesem Gemälde des Azurblauen Gewölbes dar.\"" }
entries[198515] = { ["name"] = "Die Feuerlabore", ["text"] = "Questgegenstand\n\"Dieses Gemälde von Neltharus ist kaum mehr als eine vage Ansammlung roter, orangener und schwarzer Kleckse.\"" }
entries[198516] = { ["name"] = "Hudsons finale Zeichnung", ["text"] = "Questgegenstand\n\"Eine unvollendete Zeichnung von Hudson und Ranpiata. Ihre Köpfe sind eng beieinander, während sie lächeln.\"" }
entries[198517] = { ["name"] = "Pelz von Konkhular", ["text"] = "Questgegenstand\n\"Die Farbe dieses Pelzes fügt sich gut in die Felsen und die Erde in der Umgebung.\"" }
