entries[198529] = { ["name"] = "Eiserne Fackel des Wanderers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass die Fackel Euch in Licht hüllt und Euch um 22705 Gesundheit heilt. Die Heilung der Fackel ist umso stärker, je niedriger Eure Gesundheit ist.\nVerkaufspreis:" }
entries[198530] = { ["name"] = "Rohe Zandalichilis", ["text"] = "Questgegenstand\nBenutzen: Werft dies auf die Kochfeuerstelle im Drachenschuppenbasislager, um gegrillte Zandalichilis herzustellen. (3 Sek. Abklingzeit)\n70 ( 70)\n\"Ungekocht hart und unangenehm scharf.\"" }
entries[198532] = { ["name"] = "Die Messschieber des Kartografen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, einem der Ziele mit der niedrigsten Gesundheit innerhalb von 10 Metern 7802 Schaden zuzufügen oder das Ziel um 11717 Gesundheit zu heilen, je nachdem, welchen Zauber Ihr wirkt.\n\"Es gibt eine Sache, die einen Meister vom Rest der Kartografen abhebt: Präzision.\"\nVerkaufspreis:" }
entries[198533] = { ["name"] = "Rezept: Luftgetränkte Phiole der schnellen Hände", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine luftgetränkte Phiole der schnellen Hände herstellt.\nBenötigt Alchemie der Dracheninseln\n(10)\nBenötigt die Rufstufe \"Respektiert\" beim Handwerkerkonsortium.\nVerkaufspreis:" }
entries[198537] = { ["name"] = "Taivans Trompete", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört Taivan an Eure Seite. Taivan erhöht die Vielseitigkeit aller in der Nähe um 1 . (5 Min Abklingzeit)\n\"Taivan liebt den Klang dieser aus Riesenwildschafhorn gefertigten Trompete.\"" }
entries[198538] = { ["name"] = "Magisch gebundene Nachricht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein hypnotisierender, violetter Staub strömt langsam aus dem mysteriösen Pergament und zerstreut sich nach einem flüchtigen Moment.\"" }
