entries[198541] = { ["name"] = "Aufgebrauchte violette Dämpfe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Überreste der Nachricht fühlen sich schwerelos an. Ein floraler Duft verbleibt in der Luft.\"\nVerkaufspreis:" }
